// ---- Gate Validation (after Agent 3: Integration Designer) ----
// ENFORCES documentation grounding: never falls back, never invents endpoints.
// Keeps only documented params; ADDS documented params only when the requirement
// explicitly needs them (dates for previous-day, status, customer scope).
// Any unsupported field from grounding is passed through as unsupported_fields
// so later agents cannot ignore it.

const KB_ENDPOINTS = [
  { id: 'get_single_order', method: 'GET', path: '/orders/{order_id}',
    path_params: ['order_id'], query_params: [] },
  { id: 'list_orders', method: 'GET', path: '/orders',
    path_params: [], query_params: ['start_date','end_date','status','customer_id','page','limit'] },
  { id: 'get_customer', method: 'GET', path: '/customers/{customer_id}',
    path_params: ['customer_id'], query_params: [] },
  { id: 'get_order_delivery', method: 'GET', path: '/orders/{order_id}/delivery',
    path_params: ['order_id'], query_params: [] }
];

function grab(nodeName) {
  const item = $(nodeName).first().json;
  if (item && typeof item === 'object') {
    if (typeof item.output === 'string') {
      const s = item.output.trim();
      try { return JSON.parse(s); } catch (e) {}
      const fence = s.match(/```(?:json)?\s*([\s\S]*?)```/);
      if (fence) { try { return JSON.parse(fence[1].trim()); } catch (e2) {} }
      const start = s.indexOf('{');
      const end = s.lastIndexOf('}');
      if (start > -1 && end > start) {
        try { return JSON.parse(s.slice(start, end + 1)); } catch (e3) {}
      }
      return s;
    }
    if (item.output && typeof item.output === 'object') return item.output;
    return item;
  }
  return item;
}

function isoDaysAgo(n) {
  const d = new Date();
  d.setDate(d.getDate() - n);
  return d.toISOString().slice(0, 10);
}

// 1. Grounded matches from Agent 2. NO fallback: if grounding matched nothing,
//    the design cannot be grounded and the gate REJECTS it.
const grounding = grab('Agent 2: Documentation Grounding') || {};
const groundedList = (grounding.matched_endpoints || []).map(e => e.endpoint_id);
const validEpIds = new Set(groundedList);
const passThroughUnsupported = grounding.unsupported_fields || [];

if (groundedList.length === 0) {
  throw new Error('Gate rejected: Documentation Grounding matched no endpoints; cannot ground the design.');
}

// 2. Design from Agent 3.
const design = grab('Agent 3: Integration Designer') || {};

// 3. Endpoint id: only exact grounded matches allowed.
let endpointId = design.endpoint_id || design.endpoint || '';
if (!validEpIds.has(endpointId)) {
  endpointId = groundedList.find(id => endpointId.includes(id)) || '';
}
if (!validEpIds.has(endpointId)) {
  throw new Error(`Gate rejected: endpoint '${endpointId}' not in grounded matches [${groundedList.join(', ')}]`);
}

// 4. Keep only params the knowledge base documents for that endpoint.
const ep = KB_ENDPOINTS.find(e => e.id === endpointId);
const validQuery = new Set(ep ? ep.query_params : []);
const validPath = new Set(ep ? ep.path_params : []);
const filteredParams = (design.params || []).filter(p => {
  if (p.location === 'query') return validQuery.has(p.name);
  if (p.location === 'path') return validPath.has(p.name);
  return false; // header/invented params are dropped
});

// 5. ADD documented params the requirement explicitly needs (from Agent 1).
const parsed = grab('Agent 1: Requirement Interpreter') || {};
const requirementText = [
  parsed.business_requirement || '',
  (parsed.filters || []).map(f => `${f.field}: ${f.value}`).join(' '),
  parsed.entities ? parsed.entities.join(' ') : ''
].join(' ').toLowerCase();

const wantsPreviousDay = /previous day|yesterday|last 24|past day|prior day|last day/.test(requirementText);
const wantsDateRange = /date range|between|created_at|created date|creation date/.test(requirementText);
const statusFilter = (parsed.filters || []).find(f => /status/.test(String(f.field || '').toLowerCase()));
const customerFilter = (parsed.filters || []).find(f => /customer/i.test(String(f.field || '').toLowerCase()));

const hasQuery = name => filteredParams.some(p => p.name === name);
// Fill an existing to-be-filled param when the requirement gives us the value.
function fillParam(name, value, source) {
  const p = filteredParams.find(x => x.name === name);
  if (p) {
    p.value = value;
    p.source = source;
  } else {
    filteredParams.push({ name, location: 'query', value, required: false, source });
  }
}

if (ep && ep.id === 'list_orders') {
  if (/completed|finished/.test(requirementText) || (statusFilter && String(statusFilter.value || '').toLowerCase() === 'completed')) {
    fillParam('status', 'completed', 'parsed requirement');
  } else if (statusFilter && statusFilter.value) {
    fillParam('status', String(statusFilter.value).toLowerCase(), 'parsed requirement');
  }
  // Dates: only set a concrete value when the requirement makes it determinable.
  if (wantsPreviousDay) {
    const y = isoDaysAgo(1); // YYYY-MM-DD
    fillParam('start_date', y, 'previous day');
    fillParam('end_date', y, 'previous day');
  } else if (wantsDateRange) {
    // User will pick the range at runtime -> keep as explicit to-be-filled review item
    // (documented param name; value is a developer review confirmation).
    if (!hasQuery('start_date')) filteredParams.push({ name: 'start_date', location: 'query', value: 'to-be-filled', required: false, source: 'selected date range' });
    if (!hasQuery('end_date')) filteredParams.push({ name: 'end_date', location: 'query', value: 'to-be-filled', required: false, source: 'selected date range' });
  }
  if (customerFilter && customerFilter.value) {
    fillParam('customer_id', String(customerFilter.value), 'parsed requirement');
  }
}

// 6. expected_fields: normalize names (customer -> customer_id, total amount -> total,
//    date -> created_at, etc.), then keep only documented names for this endpoint.
const FIELD_SYNONYMS = {
  'customer': 'customer_id', 'customer id': 'customer_id', 'customer number': 'customer_id',
  'date': 'created_at', 'created date': 'created_at', 'creation date': 'created_at',
  'order date': 'created_at', 'completed date': 'created_at', 'completion date': 'created_at',
  'order status': 'status', 'order state': 'status',
  'order total': 'total', 'total amount': 'total', 'amount': 'total',
  'payment status': 'payment_status',
  'order': 'order_id', 'order number': 'order_id', 'order id': 'order_id',
  'delivery status': 'delivery_status',
  'unit price': 'unit_price', 'product id': 'product_id'
};
function normField(name) {
  const n = String(name).toLowerCase().trim().replace(/_/g, ' ').split(/\s+/).map(s => s.trim()).join(' ');
  return FIELD_SYNONYMS[n] || String(name);
}
const docFields = {
  get_single_order: ['order_id','customer_id','created_at','status','payment_status','total','currency','items'],
  list_orders: ['page','limit','total_records','orders','order_id','customer_id','created_at','status','payment_status','total','currency'],
  get_customer: ['customer_id','name','email','customer_since'],
  get_order_delivery: ['order_id','delivery_status','carrier','tracking_reference','estimated_delivery']
};
let expectedFields = (design.expected_fields || []).map(normField);
expectedFields = [...new Set(expectedFields)];
expectedFields = expectedFields.filter(f => (docFields[endpointId] || []).includes(f));

const final_ = {
  ...design,
  endpoint_id: endpointId,
  params: filteredParams,
  expected_fields: expectedFields,
  unsupported_fields: passThroughUnsupported,
  gate_grounded: true
};

return [{ json: final_ }];

// ---- Agent 4: Constraint Engine (DETERMINISTIC) ----
// Applies ONLY the documented constraints: X-API-Key auth, 100 req/min rate
// limit, page/limit max 50 on List Orders, and documented error codes.
// Data minimization = only the fields the plan will actually request.

const RATE_LIMIT_PER_MIN = 100;   // from docs
const PAGE_LIMIT = 50;            // from docs
const DOC_ERRORS = [400, 401, 403, 404, 429, 500, 503]; // documented codes
const FREQ_CALLS = { 'daily': 2, 'every 2 hours': 12, 'every hour': 24, 'weekly': 2, 'on demand': 1, 'not stated': 2 };

function grab(nodeName) {
  const item = $(nodeName).first().json;
  if (item && typeof item === 'object') {
    if (typeof item.output === 'string') {
      const s = item.output.trim();
      try { return JSON.parse(s.replace(/```(?:json)?\s*/gm, '').replace(/```$/gm, '')); } catch (e) {
        const start = s.indexOf('{');
        const end = s.lastIndexOf('}');
        if (start === -1 || end === -1) return {};
        try { return JSON.parse(s.slice(start, end + 1)); } catch (e2) { return {}; }
      }
    }
    if (item.output && typeof item.output === 'object') return item.output;
    return item;
  }
  return item || {};
}

const parsed = grab('Agent 1: Requirement Interpreter') || {};
const design = grab('Gate Validation') || {}; // already grounded

const frequency = (parsed.frequency || 'not stated').toLowerCase();
const scope = parsed.scope || 'single_record';
const endpointId = design.endpoint_id || '';

const paginationNeeded = endpointId === 'list_orders' && scope !== 'single_record';

// Auth: documented X-API-Key (generic instructions only; never a credential).
const auth = {
  type: 'api_key',
  header_name: 'X-API-Key',
  call: "Include header 'X-API-Key: <key>' on every request. Key is provisioned by ConnectX; never hardcode or expose it."
};

// Rate limit risk based on documented 100 req/min ceiling.
const callsPerMin = FREQ_CALLS[frequency] || 2;
let rate_limit_risk = 'low';
if (callsPerMin * 1.5 >= RATE_LIMIT_PER_MIN || frequency === 'every 2 hours') rate_limit_risk = 'medium';
if (frequency === 'every hour' && paginationNeeded) rate_limit_risk = 'high';

// Relevant error codes chosen only from the documented set.
const relevant = [401];
if (endpointId === 'get_single_order' || endpointId === 'get_customer' || endpointId === 'get_order_delivery') relevant.push(400, 404);
if (paginationNeeded) relevant.push(429);
if (scope === 'multiple_records' || scope === 'summary_or_report') relevant.push(429);
relevant.push(500, 503);
const relevant_errors = [...new Set(relevant)].filter(c => DOC_ERRORS.includes(c)).sort();

const blockers = [];
if (paginationNeeded && !design.pagination_plan) {
  blockers.push('Pagination: List Orders returns max 50 records per request; plan must page (page/limit).');
}

const risks = [];
if (frequency === 'every hour' && paginationNeeded) {
  risks.push('Hourly full sync with pagination risks exceeding the documented 100 req/min rate limit.');
}
if (design.params && design.params.some(p => p.name === 'start_date' || p.name === 'end_date')
    && !design.params.every(p => !['start_date','end_date'].includes(p.name) || /^\d{4}-\d{2}-\d{2}$/.test(p.value))) {
  risks.push('Dates must be provided in YYYY-MM-DD format.');
}

// Data minimization: compare requested fields vs all documented fields.
const ALL_DOC_FIELDS = {
  get_single_order: ['order_id','customer_id','created_at','status','payment_status','total','currency','items'],
  list_orders: ['page','limit','total_records','orders','order_id','customer_id','created_at','status','payment_status','total','currency'],
  get_customer: ['customer_id','name','email','customer_since'],
  get_order_delivery: ['order_id','delivery_status','carrier','tracking_reference','estimated_delivery']
};
const requestedFields = (design.expected_fields || []);
const allFields = ALL_DOC_FIELDS[endpointId] || [];
const data_minimization = `Fetch only the ${requestedFields.length} needed field(s) (${requestedFields.join(', ') || 'none'}) of ${allFields.length} documented fields for ${endpointId}.`;

return [{ json: {
  auth,
  auth_required: true, auth_header: 'X-API-Key',
  pagination_needed: paginationNeeded, pagination_limit: PAGE_LIMIT,
  rate_limit_per_min: RATE_LIMIT_PER_MIN,
  rate_limit_risk,
  relevant_errors: relevant_errors,
  data_minimization,
  blockers,
  risks
}}];

