// ---- Verifier (after Agent 5: Plan Synthesizer) ----
// Source of truth = the GATE output (endpoint_id, params, expected_fields).
// grounded = true ONLY when every recommended endpoint, param, and field is
// supported by the documentation. If ANY requested item is unsupported, the
// plan is grounded:false and the problem is identified (the plan must surface
// the unsupported item instead of ignoring it).

const KB = {
  "endpoints": [
    {
      "id": "get_single_order", "method": "GET", "path": "/orders/{order_id}",
      "path_params": [{"name": "order_id", "required": true}],
      "query_params": [],
      "response_fields": [
        {"name": "order_id"}, {"name": "customer_id"}, {"name": "created_at"},
        {"name": "status"}, {"name": "payment_status"}, {"name": "total"},
        {"name": "currency"}, {"name": "items", "nested": [
          {"name": "product_id"}, {"name": "name"}, {"name": "quantity"}, {"name": "unit_price"}
        ]}
      ]
    },
    {
      "id": "list_orders", "method": "GET", "path": "/orders",
      "path_params": [],
      "query_params": [
        {"name": "start_date"}, {"name": "end_date"}, {"name": "status"},
        {"name": "customer_id"}, {"name": "page"}, {"name": "limit"}
      ],
      "response_fields": [
        {"name": "page"}, {"name": "limit"}, {"name": "total_records"},
        {"name": "orders", "nested": [
          {"name": "order_id"}, {"name": "customer_id"}, {"name": "created_at"},
          {"name": "status"}, {"name": "payment_status"}, {"name": "total"}, {"name": "currency"}
        ]}
      ]
    },
    {
      "id": "get_customer", "method": "GET", "path": "/customers/{customer_id}",
      "path_params": [{"name": "customer_id", "required": true}],
      "query_params": [],
      "response_fields": [
        {"name": "customer_id"}, {"name": "name"}, {"name": "email"}, {"name": "customer_since"}
      ]
    },
    {
      "id": "get_order_delivery", "method": "GET", "path": "/orders/{order_id}/delivery",
      "path_params": [{"name": "order_id", "required": true}],
      "query_params": [],
      "response_fields": [
        {"name": "order_id"}, {"name": "delivery_status"}, {"name": "carrier"},
        {"name": "tracking_reference"}, {"name": "estimated_delivery"}
      ]
    }
  ]
};

function flatten(ep) {
  const out = [];
  for (const f of (ep.response_fields || [])) {
    out.push(f.name);
    for (const n of (f.nested || [])) out.push(n.name);
  }
  return out;
}

function endpointById(id) {
  return KB.endpoints.find(e => e.id === id) || null;
}

function grab(nodeName) {
  const item = $(nodeName).first().json;
  if (item && typeof item === 'object') {
    if (typeof item.output === 'string') {
      const s = item.output.trim();
      try { return JSON.parse(s.replace(/^```(?:json)?\s*/gm, '').replace(/```$/gm, '')); } catch (e) {
        const fence = s.match(/```(?:json)?\s*([\s\S]*?)```/);
        if (fence) { try { return JSON.parse(fence[1].trim()); } catch (e2) {} }
        const start = s.indexOf('{');
        const end = s.lastIndexOf('}');
        if (start > -1 && end > start) {
          try { return JSON.parse(s.slice(start, end + 1)); } catch (e3) {}
        }
        return {};
      }
    }
    if (item.output && typeof item.output === 'object') return item.output;
    return item;
  }
  return item || {};
}

const gate = grab('Gate Validation') || {};
const grounding = grab('Agent 2: Documentation Grounding') || {};
const plan = grab('Agent 5: Plan Synthesizer') || {};

const checks = [];
const problems = [];

// 0. Grounding must have matched something (later agents must not ignore no-match).
const groundedCount = (grounding.matched_endpoints || []).length;
if (groundedCount === 0) {
  checks.push({ item: 'grounding', checked_against: 'knowledge base', status: 'violation',
    detail: 'Documentation Grounding matched no endpoints; later agents ignored this.' });
  problems.push('Documentation Grounding matched no endpoints.');
}

// 0b. ANY requested item the docs do not support => grounded:false (identified).
const unsupported = grounding.unsupported_fields || [];
const planUnsupported = (plan.unsupported_requirements || []).map(String);
for (const u of unsupported) {
  checks.push({ item: `unsupported item '${u}'`, checked_against: 'knowledge base', status: 'violation',
    detail: `Requested item '${u}' is NOT supported by the documentation and must be reported as unsupported.` });
  problems.push(`Unsupported item '${u}'.`);
  if (!planUnsupported.some(p => p.toLowerCase().includes(String(u).toLowerCase()))) {
    checks.push({ item: `unsupported item '${u}' surfaced`, checked_against: 'plan', status: 'violation',
      detail: `Plan did not list '${u}' in unsupported_requirements.` });
    problems.push(`Plan did not surface unsupported item '${u}'.`);
  }
}

// 1. Endpoint: must be documented + grounded.
const gateEndpointId = gate.endpoint_id || '';
const gateEp = endpointById(gateEndpointId);
if (!gateEp) {
  checks.push({ item: 'endpoint', checked_against: 'knowledge base', status: 'violation',
    detail: `Gate endpoint '${gateEndpointId}' is not in the ConnectX API documentation` });
  problems.push(`Endpoint '${gateEndpointId}' is not documented.`);
}
const epById = gateEp || { id: gateEndpointId, path_params: [], query_params: [], response_fields: [] };

// 2. Params: documented only; required path params present; dates YYYY-MM-DD.
const providedPath = (gate.params || []).filter(p => p.location === 'path').map(p => p.name);
for (const req of (epById.path_params || [])) {
  if (req.required && !providedPath.includes(req.name)) {
    checks.push({ item: `path param ${req.name}`, checked_against: epById.id, status: 'violation',
      detail: `required path parameter '${req.name}' is missing from the plan` });
    problems.push(`Missing required path param '${req.name}'.`);
  }
}

const allowedQuery = new Set((epById.query_params || []).map(p => p.name));
for (const p of (gate.params || [])) {
  if (p.location === 'query' && !allowedQuery.has(p.name)) {
    checks.push({ item: `query param ${p.name}`, checked_against: epById.id, status: 'violation',
      detail: `'${p.name}' is not a documented query parameter of ${epById.id}` });
    problems.push(`Undocumented query param '${p.name}'.`);
  }
  if (p.name === 'start_date' || p.name === 'end_date') {
    const raw = String(p.value || '').trim();
    if (!raw || raw === 'to-be-filled') {
      checks.push({ item: `query param ${p.name}`, checked_against: epById.id, status: 'warning',
        detail: `'${p.name}' value is '${raw}' and must be filled with ${'YYYY-MM-DD'} at runtime` });
    } else if (!/^\d{4}-\d{2}-\d{2}$/.test(raw)) {
      checks.push({ item: `query param ${p.name}`, checked_against: epById.id, status: 'violation',
        detail: `'${p.name}' must be YYYY-MM-DD, got '${raw}'` });
      problems.push(`Date '${p.name}' not in YYYY-MM-DD.`);
    }
  }
}

// 3. Response fields: documented for the endpoint only.
const validFields = new Set(flatten(epById));
for (const f of (gate.expected_fields || [])) {
  if (!validFields.has(f)) {
    checks.push({ item: `response field ${f}`, checked_against: epById.id, status: 'violation',
      detail: `'${f}' is not a documented response field of ${epById.id}` });
    problems.push(`Response field '${f}' is not documented.`);
  }
}

// 4. Agent 5 endpoint must agree with the Gate endpoint.
const planEpRaw = plan.recommended_endpoint || '';
const [method, ...rest] = planEpRaw.split(' ');
const pathStr = (rest.join(' ') || '').split('?')[0];
const planEp = KB.endpoints.find(e =>
  e.method.toUpperCase() === String(method || '').toUpperCase() &&
  e.path.replace(/\//g, '') === (pathStr || '').replace(/\//g, ''));
if (planEpRaw) {
  if (!planEp) {
    checks.push({ item: 'plan endpoint', checked_against: 'knowledge base', status: 'violation',
      detail: `Plan recommended '${planEpRaw}' which is not a documented endpoint` });
    problems.push(`Plan endpoint '${planEpRaw}' not documented.`);
  } else if (gateEp && planEp.id !== gateEp.id) {
    checks.push({ item: 'endpoint agreement', checked_against: gateEp.id, status: 'violation',
      detail: `Plan recommended ${planEp.id} but Gate selected ${gateEp.id}` });
    problems.push(`Plan endpoint ${planEp.id} disagrees with Gate endpoint ${gateEp.id}.`);
  }
  const q = (planEpRaw.split('?')[1] || '').split('&').map(s => s.split('=')[0]).filter(Boolean);
  const planAllowed = new Set((planEp ? planEp.query_params : []).map(p => p.name));
  for (const qp of q) {
    if (!planAllowed.has(qp)) {
      checks.push({ item: `plan query param ${qp}`, checked_against: planEp ? planEp.id : '?', status: 'violation',
        detail: `Plan used query param '${qp}' which is not documented for the endpoint` });
      problems.push(`Plan query param '${qp}' is not documented.`);
    }
  }
}

const grounded = problems.length === 0;
let summary = 'Every endpoint, parameter, and field in the plan is supported by the documentation.';
if (!grounded) summary = `${checks.filter(c => c.status === 'violation').length} problem(s) found: ${problems.join(' ')}`;

return [{ json: { checks, grounded, summary, problems } }];

